200	fn json_type_matches(expected: &str, value: &serde_json::Value) -> bool {
201	    match expected {
202	        "object" => value.is_object(),
203	        "array" => value.is_array(),
204	        "string" => value.is_string(),
205	        "number" => value.is_number(),
206	        "integer" => value.is_i64() || value.is_u64(),
207	        "boolean" => value.is_boolean(),
208	        "null" => value.is_null(),
209	        // Unrecognized type keyword: not enforced rather than falsely rejected.
210	        _ => true,
211	    }
212	}
