281	/// Evaluate a batch of records against a min_pass_ratio threshold (§7.6).
282	/// Pure: scores are pre-computed; this function only tallies and quarantines.
283	pub fn evaluate_batch(
284	    records: &[serde_json::Value],
285	    scores: &[f64],
286	    min_pass_ratio: f64,
287	) -> BatchEvaluationResult {
288	    let total = records.len();
289	    let mut passed = 0usize;
290	    let mut failures = Vec::new();
291	    for (i, record) in records.iter().enumerate() {
292	        let score = scores.get(i).copied().unwrap_or(0.0);
293	        if score >= 0.5 {
294	            passed += 1;
295	        } else {
296	            failures.push(BatchFailure {
297	                record: record.clone(),
298	                score,
299	                evidence_ref: format!("record_{i}"),
300	            });
301	        }
302	    }
303	    let pass_ratio = if total == 0 {
304	        1.0
305	    } else {
306	        passed as f64 / total as f64
307	    };
308	    BatchEvaluationResult {
309	        total,
310	        passed,
311	        pass_ratio,
312	        min_pass_ratio,
313	        failures,
314	    }
315	}
